import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../lib/db';

export const onGet: RequestHandler = async ({ json }) => {
  try {
    const tasks = db.prepare('SELECT * FROM tasks').all();
    json(200, tasks);
  } catch (err: any) {
    json(500, { error: err.message });
  }
};

export const onPost: RequestHandler = async ({ json, request }) => {
  try {
    const body = await request.json();
    const { id, name, command, interval_seconds, status } = body || {};

    // Validation
    if (!id || typeof id !== 'string' || id.trim() === '') {
      json(400, { error: 'Invalid or missing id' });
      return;
    }
    if (!name || typeof name !== 'string' || name.trim() === '') {
      json(400, { error: 'Invalid or missing name' });
      return;
    }
    if (!command || typeof command !== 'string' || command.trim() === '') {
      json(400, { error: 'Invalid or missing command' });
      return;
    }
    if (typeof interval_seconds !== 'number' || isNaN(interval_seconds) || interval_seconds <= 0 || !Number.isInteger(interval_seconds)) {
      json(400, { error: 'interval_seconds must be a positive integer' });
      return;
    }
    if (status !== 'ACTIVE' && status !== 'PAUSED') {
      json(400, { error: "status must be either 'ACTIVE' or 'PAUSED'" });
      return;
    }

    // Check if ID already exists
    const existing = db.prepare('SELECT id FROM tasks WHERE id = ?').get(id);
    if (existing) {
      json(400, { error: `Task with id '${id}' already exists` });
      return;
    }

    // Insert task
    db.prepare(`
      INSERT INTO tasks (id, name, command, interval_seconds, status)
      VALUES (?, ?, ?, ?, ?)
    `).run(id, name, command, interval_seconds, status);

    json(201, { id, name, command, interval_seconds, status });
  } catch (err: any) {
    json(400, { error: err.message });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../../../lib/db';

export const onPost: RequestHandler = async ({ json, params }) => {
  const { id } = params;
  try {
    const task = db.prepare('SELECT id FROM tasks WHERE id = ?').get(id);
    if (!task) {
      json(404, { error: `Task with id '${id}' not found` });
      return;
    }

    db.prepare("UPDATE tasks SET status = 'PAUSED' WHERE id = ?").run(id);

    json(200, {
      id,
      status: 'PAUSED'
    });
  } catch (err: any) {
    json(500, { error: err.message });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../../../lib/db';
import { setTaskLastExecuted } from '../../../../../lib/runner';

export const onPost: RequestHandler = async ({ json, params }) => {
  const { id } = params;
  try {
    const task = db.prepare('SELECT id FROM tasks WHERE id = ?').get(id);
    if (!task) {
      json(404, { error: `Task with id '${id}' not found` });
      return;
    }

    db.prepare("UPDATE tasks SET status = 'ACTIVE' WHERE id = ?").run(id);

    // Reset the last executed time to the current time so it executes after interval_seconds
    setTaskLastExecuted(id, Date.now());

    json(200, {
      id,
      status: 'ACTIVE'
    });
  } catch (err: any) {
    json(500, { error: err.message });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../../../lib/db';
import { runTaskCommand, setTaskLastExecuted } from '../../../../../lib/runner';

export const onPost: RequestHandler = async ({ json, params }) => {
  const { id } = params;
  try {
    const task = db.prepare('SELECT id, command FROM tasks WHERE id = ?').get(id) as { id: string, command: string } | undefined;
    if (!task) {
      json(404, { error: `Task with id '${id}' not found` });
      return;
    }

    // Trigger in background (don't await the execution, just start it)
    runTaskCommand(task.id, task.command);

    // Update lastExecuted to now so the interval schedules from this trigger
    setTaskLastExecuted(task.id, Date.now());

    json(200, {
      id,
      triggered: true
    });
  } catch (err: any) {
    json(500, { error: err.message });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../../../lib/db';

export const onGet: RequestHandler = async ({ json, params }) => {
  const { id } = params;
  try {
    const task = db.prepare('SELECT id FROM tasks WHERE id = ?').get(id);
    if (!task) {
      json(404, { error: `Task with id '${id}' not found` });
      return;
    }

    const history = db.prepare(`
      SELECT * FROM execution_history
      WHERE task_id = ?
      ORDER BY timestamp DESC, id DESC
    `).all(id);

    json(200, history);
  } catch (err: any) {
    json(500, { error: err.message });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../lib/db';

export const onGet: RequestHandler = async ({ json }) => {
  try {
    const history = db.prepare(`
      SELECT h.*, t.name as task_name
      FROM execution_history h
      JOIN tasks t ON h.task_id = t.id
      ORDER BY h.timestamp DESC, h.id DESC
      LIMIT 100
    `).all();
    json(200, history);
  } catch (err: any) {
    json(500, { error: err.message });
  }
};

